+import { Invoice } from "../types";
+
+export class InvoiceService {
+  constructor(private readonly baseUrl: string) {}
+
+  async fetchInvoices(accountId: string): Promise<Invoice[]> {
+    const res = await fetch(`${this.baseUrl}/accounts/${accountId}/invoices`);
+    return (await res.json()) as Invoice[];
+  }
+
+  isOverdue(invoice: Invoice, now: Date): boolean {
+    return invoice.dueAt.getTime() < now.getTime() && !invoice.paid;
+  }
+}

