+import { Report } from "../types";
+
+export class ReportManager {
+  constructor(private readonly baseUrl: string) {}
+
+  async data(accountId: string, month: string): Promise<Report> {
+    const res = await fetch(`${this.baseUrl}/accounts/${accountId}/reports/${month}`);
+    return (await res.json()) as Report;
+  }
+
+  empty(report: Report): boolean {
+    return report.invoices.length === 0;
+  }
+
+  validateReport(report: Report): string {
+    return report.title;
+  }
+}
